INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
  (29406, 1, 0, 0, 0, 0, 0, 0, 0, 'Not bad, $n. You may indeed have chosen the proper path.$B$BGood. Let us continue.', 0),
  (29408, 1, 0, 0, 0, 0, 0, 0, 0, 'The fact that you were able to snatch the flame so easily is no small feat.$B$BThe Edict of Temperance is a scroll of wisdom passed down from my elders'' elders. Wisdom from a more peaceful time.$B$BEvery lesson has its time and place, and with darkness on the horizon, the time for this particular wisdom has passed.$B$BThe burning of the scroll is an acceptance of tidings to come and a promise to action. Your hand carried the flame, and I suspect that it will continue to do so in the future.', 0),
  (29409, 1, 0, 0, 0, 0, 0, 0, 0, 'You truly impress, $n. It seems certain that the path of the $c is indeed the path for you.', 0),
  (29410, 1, 0, 0, 0, 0, 0, 0, 0, 'You came for Aysa? You... you really shouldn''t interrupt her until she finishes her exercises. She doesn''t speak to anyone until her routine is done.$B$BIn the meantime, could you maybe help me? I had some bad luck with forest sprites.', 0),
  (29414, 1, 0, 0, 0, 0, 0, 0, 0, 'Your path is set before you. You will be the one to rekindle the spirit of fire and bring it to the safety of the temple.$B$BThis will not be the only time you and Aysa work together. She is strong and wise. You can trust in her.', 0),
  (29417, 1, 0, 0, 0, 0, 0, 0, 0, 'You''ve got some fight in you! I think I like you!', 0),
  (29418, 1, 0, 0, 0, 0, 0, 0, 0, '$n! You''ve returned, roots in hand! You''re a down-to-business kind of $G guy:gal;, aren''t you? I like that!', 0),
  (29419, 1, 0, 0, 0, 0, 0, 0, 0, 'You are too kind, $c.', 0),
  (29420, 1, 0, 0, 0, 0, 0, 0, 0, 'Life isn''t about finding yourself. Life is about creating yourself. There is a path before you, but you choose the trials you will face, and the trials you will overcome.', 0),
  (29421, 1, 0, 0, 0, 0, 0, 0, 0, 'Remember always, the superior warrior is modest in his speech, but exceeds in his actions.', 0),
  (29422, 1, 0, 0, 0, 0, 0, 0, 0, '<Through the glare, it looks like Huo is smiling. He seems to have warmed up to you.>', 0),
  (29423, 1, 0, 0, 0, 0, 0, 0, 0, '$n, you''ve done very well. Huo, the spirit of fire, is here. The temple flames are reignited. You accomplished the challenge I put before you, and with seeming ease.$B$BThere is a greater purpose in bringing Huo to the temple. It is time that I tell you more of things to come.', 0),
  (29424, 1, 0, 0, 0, 0, 0, 0, 0, 'Thank you! You''re an honorable $c. They''ve taught you well.', 0),
  (29521, 1, 0, 0, 0, 0, 0, 0, 0, 'It''s good to see you again, $n.$B$BThis is the pool of the skunk, as I''m sure you noticed.$B$BOver the many ages of Shen-zin Su, animals have died in some of these magical pools. Through their deaths, their spirits were infused into the waters, and anyone touching those waters will take their form.$B$BThere are several cursed pools here, some more dangerous than others.', 0),
  (29522, 1, 0, 0, 0, 0, 0, 0, 0, 'Hello! You look poised and confident... I like that!$B$BI''ve heard some rather impressive whispers about you from the training grounds. If you''re half as capable as they say, I think you and I are going to be good friends!', 0),
  (29523, 1, 0, 0, 0, 0, 0, 0, 0, 'You know what it is to seize opportunity. I think you and I are kindred spirits, $n.', 0),
  (29524, 1, 0, 0, 0, 0, 0, 0, 0, 'Intriguing, my young pupil.$B$BMost of the other trainees have been here for quite some time, but you are able to match them even within this first hour.$B$BThis speaks well of you, but there are yet other lessons I would see you learn.', 0),
  (29661, 1, 0, 0, 0, 0, 0, 0, 0, 'Good. You''re a quick study.', 0),
  (29662, 0, 0, 0, 0, 0, 0, 0, 0, 'Good.$B$BNo number of reeds have ever withstood my might.$B$BStep back, and let me dispel your doubts.', 0),
  (29663, 1, 0, 0, 0, 0, 0, 0, 0, 'Even now, your skills increase. Your footing becomes more sure. Your blows strike with more force.$B$BDiscipline and practice are the keys to reaching our full potential.', 0),
  (29664, 1, 0, 0, 0, 0, 0, 0, 0, 'These fires will give you the strength that you''ve not yet obtained. They will illuminate your potential.', 0),
  (29665, 1, 0, 0, 0, 0, 0, 0, 0, 'You are a fear to behold upon the battlefield.', 0),
  (29666, 1, 0, 0, 0, 0, 0, 0, 0, 'The water pincers are strange creatures. They seem to be drawn to still water.', 0),
  (29676, 1, 0, 0, 0, 0, 0, 0, 0, 'Visitors are rare up here, but you are welcome. It is nice to meet you, young $c.', 0),
  (29677, 1, 0, 0, 0, 0, 0, 0, 0, 'Shu''s desires are not so different from our own. He does not want to be alone. Unwanted, unloved. He longs to be needed, and to share his life with others.$B$BKnowing that, earning his trust is not terribly difficult. He just wants company.', 0),
  (29779, 1, 0, 0, 0, 0, 0, 0, 0, 'Invigorating! A good fight always makes me feel better!', 0),
  (29780, 1, 0, 0, 0, 0, 0, 0, 0, '$n, I think you''ve got a bit of Huojin in you. Stick with me and I''ll bring you around, I think.', 0),
  (29781, 1, 0, 0, 0, 0, 0, 0, 0, '$n, I''m thinking we should celebrate with these later. What do you think?', 0),
  (29782, 1, 0, 0, 0, 0, 0, 0, 0, 'GOOD! A true challenge. Let us put this pillar to the test!', 0),
  (29784, 1, 0, 0, 0, 0, 0, 0, 0, 'I''m impressed. Most students that are even capable of reaching this spot do so soaking wet.', 0),
  (29785, 1, 0, 0, 0, 0, 0, 0, 0, 'Dafeng looks frightened as you approach, but settles a bit at the sound of your voice.', 0),
  (29786, 1, 0, 0, 0, 0, 0, 0, 0, 'You have helped Dafeng, the spirit of air, find his courage! The final spirit has been restored.', 0),
  (29787, 1, 0, 0, 0, 0, 0, 0, 0, 'I do not have the strength of body or will that I once did. I''m glad there are noble pandaren like you to fight on for our people. You''ve come far, $n.', 0),
  (29788, 1, 0, 0, 0, 0, 0, 0, 0, 'The spirits thank you, $c.', 0),
  (29789, 1, 0, 0, 0, 0, 0, 0, 0, 'You come through, as you always have. You are truly one of my greatest students. I think you will be something the likes of which the world has never seen.', 0),
  (29790, 1, 0, 0, 0, 0, 0, 0, 0, 'I know, $n... I know. Such is the way of things.', 0),
  (29791, 1, 0, 0, 0, 0, 0, 0, 0, 'You have undergone a great honor, $c. Have you come back wiser for it?', 0),
  (29792, 1, 0, 0, 0, 0, 0, 0, 0, 'Evil is rising from the seas and filling the forest. It''s not just tigers anymore... something far more sinister lurks in the shadows, waiting to take any pandaren unwise enough to stray out alone.$B$BYou are not safe here.', 0),
  (29793, 1, 0, 0, 0, 0, 0, 0, 0, 'You make me proud, $n. You make all of us proud.', 0),
  (29794, 1, 0, 0, 0, 0, 0, 0, 0, 'I have no idea who you people are, but fate surely smiled on us this day. Many more would be dead if not for the help of you and your friends. I am in your debt.', 0),
  (29795, 1, 0, 0, 0, 0, 0, 0, 0, 'These are excellent! We''ll have them crafted into weapons in no time.', 0),
  (29796, 1, 0, 0, 0, 0, 0, 0, 0, 'Your friend is out fighting to save my crew. Fiercely I might add. I''m afraid your message may have to wait.', 0),
  (29797, 1, 0, 0, 0, 0, 0, 0, 0, 'These will do perfectly. I''ll get my medics to work immediately.$B$BThank you.', 0),
  (29798, 1, 0, 0, 0, 0, 0, 0, 0, '<Aysa is clearly exhausted from the fight.>$B$BYour skills in battle... are unquestionable... $c.$B$B<Aysa catches her breath for a moment.>$B$BDid you save the escaped prisoners?  ...Where is Ji? Is he okay?', 0),
  (29799, 1, 0, 0, 0, 0, 0, 0, 0, 'You are a sight to see when under pressure, $n! We wouldn''t have stood a chance without you.$B$BI think it''s working. The flow of blood is slowing. I knew it would work!', 0),
  (29800, 1, 0, 0, 0, 0, 0, 0, 0, 'It is good to see you again, $n. You''ve done all that I''ve asked of you and more... you have saved Shen-zin Su.$B$BYou make an old master proud.', 0),
  (30027, 1, 0, 0, 0, 0, 0, 0, 0, 'A fine weapon. It should suit your needs well.$B$BNow let''s put it to use.', 0),
  (30033, 1, 0, 0, 0, 0, 0, 0, 0, 'A fine weapon. It should suit your needs well.$B$BNow let''s put it to use.', 0),
  (30034, 1, 0, 0, 0, 0, 0, 0, 0, 'A fine weapon. It should suit your needs well.$B$BNow let''s put it to use.', 0),
  (30035, 1, 0, 0, 0, 0, 0, 0, 0, 'A fine weapon. It should suit your needs well.$B$BNow let''s put it to use.', 0),
  (30036, 1, 0, 0, 0, 0, 0, 0, 0, 'A fine weapon. It should suit your needs well.$B$BNow let''s put it to use.', 0),
  (30037, 1, 0, 0, 0, 0, 0, 0, 0, 'A fine weapon. It should suit your needs well.$B$BNow let''s put it to use.', 0),
  (30038, 1, 0, 0, 0, 0, 0, 0, 0, 'A fine weapon. It should suit your needs well.$B$BNow let''s put it to use.', 0),
  (30589, 1, 0, 0, 0, 0, 0, 0, 0, 'Korga sent you, eh? Well, I wouldn''t mind doing a number on that ship for my own reasons anyway, but it''s going to take some work.$B$BGive me a moment to think...', 0),
  (30590, 1, 0, 0, 0, 0, 0, 0, 0, 'More than enough. I''ve got the main control panel constructed. We should be ready very soon!', 0),
  (30591, 1, 0, 0, 0, 0, 0, 0, 0, 'These survivors are in your debt, $c.', 0),
  (30767, 1, 0, 0, 0, 0, 0, 0, 0, 'The first step is done, but now we must save Shen-zin Su!', 0),
  (30987, 273, 0, 0, 0, 0, 0, 0, 0, 'Pandaren... you''re here.$b$bGood.', 0),
  (31450, 1, 0, 0, 0, 0, 0, 0, 0, 'And so it is done... here we are, in our new home.', 0);
